pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value) public {
        vm.assume(_value <= type(uint256).max / 2); // avoid overflow in doubled version
        vm.assume(_value >= 10); // ticket amount
        // Ensure enough ETH from caller
        vm.deal(address(this), address(this).balance + _value);
        // Record pot before
        uint256 before = c.pot();
        // Make the play
        try this.playHelper(_value) {
            // If no revert, check the rule after the call
            uint256 after = c.pot();
            // The rule: pot increased by exactly msg.value (10), not doubled
            assertTrue(after == before + 10 || after == 0, "Pot not increased correctly");
        } catch {
            // If revert, pot shouldn't change
            uint256 after = c.pot();
            assertTrue(after == before, "Pot changed on revert");
        }
    }

    function playHelper(uint256 value) external payable {
        // This helper is needed because try/catch cannot call payable functions directly
        // Instead, we use a trick: call c.play{value: value}() in a separate context
        // Actually simpler: just call c.play() directly with value from this contract
        (bool success, ) = address(c).call{value: value}(abi.encodeWithSignature("play()"));
        require(success, "play failed");
    }
}

