        uint potBefore = c.pot();
        uint bankBefore = address(c.bank()).balance;
        uint balanceBefore = address(this).balance;
        uint callerBalanceBefore = address(caller).balance;

        // The reference C sends 10 wei but we need exactly 10 wei
        vm.assume(potBefore < type(uint).max - 10);

        bool success = address(c).call{value: 10 wei}(abi.encodeWithSignature("play()"));

