            assertTrue(potAfter == 0);
            assertEq(address(c.bank()).balance, bankBefore + 1);
            assertEq(address(caller).balance, callerBalanceBefore + potBefore + 10 - 1);
        } else {
            // no payout: pot increased by 10
            assertTrue(potAfter == potBefore + 10);
            assertEq(address(c.bank()).balance, bankBefore);
            assertEq(address(caller).balance, callerBalanceBefore);
        }
    }
}

